def separate_paren_groups(paren_string: str) -> List[str]:
    def is_valid_group(sub_string):
        stack = []
        for char in sub_string:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    result = []
    current_group = ''
    index = 0
    while index < len(paren_string):
        i = paren_string.find('(', index)
        if i == -1:
            break
        j = paren_string.find(')', i)
        if j == -1:
            break
        group = paren_string[i:j+1]
        if is_valid_group(group):
            result.append(group)
            index = j + 1
        else:
            current_group += paren_string[i:j+1]
        index = j + 1
    if current_group:
        if is_valid_group(current_group):
            result.append(current_group)
    return result
```

