from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    visited = set()
    path = []

    def dfs(x, y, path_len):
        if path_len == k:
            return True
        if path_len > k or len(path) == k and path_len + N - len(path) < k:
            return False

        visited.add((x, y))
        path.append(grid[x][y])

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and ((nx, ny) not in visited):
                if dfs(nx, ny, path_len + 1):
                    return True

        path.pop()
